"""Generated by LeanFM from protocol Lending; regenerate it with session_skeleton rather than editing.

Each role's states are classes; a method consumes its state and returns the next. The start
functions are member, desk, librarian. A transport is a function that takes a message
(the logged event plus a body) and delivers it; log, if given, receives every event for
session_conform.
"""

import itertools


class ProtocolError(Exception):
    """A step the protocol does not allow here."""


class Endpoint:
    """One role in one session. It numbers events, binds the protocol's message ids to the events
    that were those messages, fills in causes, logs every event, and hands messages to transport."""

    def __init__(self, role, session, transport, log=None, new_id=None):
        self.role, self.session = role, str(session)
        self.transport, self.log = transport, log
        counter = itertools.count(1)
        self.new_id = new_id or (lambda: f"{self.session}.{self.role}.{next(counter)}")
        self.bind = {}

    def send(self, to, label, pid, cause_pid, body, cause=None):
        if cause is None and cause_pid is not None:
            cause = self.bind.get(cause_pid)
            if cause is None:
                raise ProtocolError(f"{label} is caused by {cause_pid}, which has not happened in session {self.session}")
        event = {"id": self.new_id(), "session": self.session, "from": self.role, "to": to, "label": label}
        if cause is not None:
            event["cause"] = cause
        if pid is not None:
            self.bind[pid] = event["id"]
        if self.log is not None:
            self.log(dict(event))
        self.transport(dict(event, body={} if body is None else body))
        return event

    def act(self, label):
        event = {"id": self.new_id(), "session": self.session, "at": self.role, "label": label, "act": True}
        if self.log is not None:
            self.log(dict(event))
        return event

    def accepts(self, msg, src, label):
        return msg.get("label") == label and msg.get("from") == src and msg.get("to") == self.role

    def received(self, msg, pid):
        if str(msg.get("session")) != self.session:
            raise ProtocolError(f"a message of session {msg.get('session')} reached session {self.session}")
        if pid is not None:
            self.bind[pid] = msg["id"]

    def refuse(self, state, msg, allowed):
        raise ProtocolError(f"{self.role} in {state} cannot receive {msg.get('label')} from {msg.get('from')}; "
                            f"it accepts {allowed}")


class State:
    """A typestate state. Each is used once: a method consumes it and returns the next state."""

    def __init__(self, ep):
        self._ep, self._used = ep, False

    def _take(self):
        if self._used:
            raise ProtocolError(f"{type(self).__name__} was already used; continue from the state it returned")
        self._used = True
        return self._ep

    @property
    def endpoint(self):
        return self._ep


class End(State):
    """The role has finished this session."""


class Fork:
    """Concurrent branches: run each state in branches toward End, then join to continue. For par,
    join with the End of every branch. For join k, join once k branches have ended and keep running
    the others beside what follows; the typestate does not carry k, so session_conform checks it."""

    def __init__(self, branches, then):
        self.branches, self._then, self._joined = branches, then, False

    def join(self, *ends):
        if self._joined:
            raise ProtocolError("this fork was already joined")
        if not ends or len(ends) > len(self.branches) or not all(isinstance(e, End) for e in ends):
            raise ProtocolError("join takes the End of each branch that has finished")
        self._joined = True
        return self._then()


class Server:
    """Any number of sessions of the same body, each with its own endpoint."""

    def __init__(self, ep, start, then):
        self._ep, self._start, self._then = ep, start, then

    def session(self, session, transport=None, log=None, new_id=None):
        ep = Endpoint(self._ep.role, session, transport or self._ep.transport, log or self._ep.log, new_id)
        return self._start(ep)

    def then(self):
        return self._then(self._ep)


class MemberS1(State):
    """Member at S1: send_borrow → MemberS2."""

    def send_borrow(self, body=None):
        ep = self._take()
        ep.send("Desk", "Borrow", "b", None, body)
        return MemberS2(ep)


class MemberS2(State):
    """Member at S2: receive(msg): Lent from Desk, Waitlisted from Desk, Refused from Desk."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Desk", "Lent"):
            self._take()
            ep.received(msg, "l")
            return msg, MemberS3(ep)
        if ep.accepts(msg, "Desk", "Waitlisted"):
            self._take()
            ep.received(msg, None)
            return msg, End(ep)
        if ep.accepts(msg, "Desk", "Refused"):
            self._take()
            ep.received(msg, None)
            return msg, End(ep)
        ep.refuse("MemberS2", msg, "Lent from Desk, Waitlisted from Desk, Refused from Desk")


class MemberS3(State):
    """Member at S3: send_return → MemberS4."""

    def send_return(self, body=None):
        ep = self._take()
        ep.send("Desk", "Return", "r", None, body)
        return MemberS4(ep)


class MemberS4(State):
    """Member at S4: receive(msg): Returned from Desk."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Desk", "Returned"):
            self._take()
            ep.received(msg, None)
            return msg, End(ep)
        ep.refuse("MemberS4", msg, "Returned from Desk")


def member(session, transport, log=None, new_id=None):
    """Member's start state in a new session."""
    return MemberS1(Endpoint("Member", session, transport, log, new_id))


class DeskS1(State):
    """Desk at S1: receive(msg): Borrow from Member."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Member", "Borrow"):
            self._take()
            ep.received(msg, "b")
            return msg, DeskS2(ep)
        ep.refuse("DeskS1", msg, "Borrow from Member")


class DeskS2(State):
    """Desk at S2: send_lent → DeskS3; send_hold → DeskS5."""

    def send_lent(self, body=None):
        ep = self._take()
        ep.send("Member", "Lent", "l", "b", body)
        return DeskS3(ep)

    def send_hold(self, body=None):
        ep = self._take()
        ep.send("Librarian", "Hold", "h", "b", body)
        return DeskS5(ep)


class DeskS3(State):
    """Desk at S3: receive(msg): Return from Member."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Member", "Return"):
            self._take()
            ep.received(msg, "r")
            return msg, DeskS4(ep)
        ep.refuse("DeskS3", msg, "Return from Member")


class DeskS4(State):
    """Desk at S4: send_returned → End."""

    def send_returned(self, body=None):
        ep = self._take()
        ep.send("Member", "Returned", None, "r", body)
        return End(ep)


class DeskS5(State):
    """Desk at S5: receive(msg): Approved from Librarian, Denied from Librarian."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Librarian", "Approved"):
            self._take()
            ep.received(msg, None)
            return msg, DeskS6(ep)
        if ep.accepts(msg, "Librarian", "Denied"):
            self._take()
            ep.received(msg, None)
            return msg, DeskS7(ep)
        ep.refuse("DeskS5", msg, "Approved from Librarian, Denied from Librarian")


class DeskS6(State):
    """Desk at S6: send_waitlisted → End."""

    def send_waitlisted(self, body=None):
        ep = self._take()
        ep.send("Member", "Waitlisted", None, "b", body)
        return End(ep)


class DeskS7(State):
    """Desk at S7: send_refused → End."""

    def send_refused(self, body=None):
        ep = self._take()
        ep.send("Member", "Refused", None, "b", body)
