def desk(session, transport, log=None, new_id=None):
    """Desk's start state in a new session."""
    return DeskS1(Endpoint("Desk", session, transport, log, new_id))


class LibrarianS1(State):
    """Librarian at S1: receive(msg): Hold from Desk; skip → End (the branch taken did not involve this role)."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Desk", "Hold"):
            self._take()
            ep.received(msg, "h")
            return msg, LibrarianS2(ep)
        ep.refuse("LibrarianS1", msg, "Hold from Desk")

    def skip(self):
        return End(self._take())


class LibrarianS2(State):
    """Librarian at S2: send_approved → End; send_denied → End."""

    def send_approved(self, body=None):
        ep = self._take()
        ep.send("Desk", "Approved", None, "h", body)
        return End(ep)

    def send_denied(self, body=None):
        ep = self._take()
        ep.send("Desk", "Denied", None, "h", body)
        return End(ep)


def librarian(session, transport, log=None, new_id=None):
    """Librarian's start state in a new session."""
    return LibrarianS1(Endpoint("Librarian", session, transport, log, new_id))
